import json,uuid,copy,hashlib,re
from pathlib import Path
from fractions import Fraction as F
base=Path(__file__).resolve().parent
catalog=Path('curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_PHYSIK.de.json'); goals={g['id']:g for g in json.loads(catalog.read_text())['goals']}

def make(key, covered, title, title_en, description, description_en, de,en,solution_de,solution_en,criteria):
 g=goals[covered]; ident=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://skillpilot.com/goals/physics/'+key+'-20261117'))
 rubric_de='Bewertung: Acht Kernleistungen, jeweils 3 BE bei vollständiger fachlich korrekter Leistung; 2 BE nur bei vollständig erbrachtem Kern mit einem isolierten nicht konzeptionellen Rechen-, Rundungs- oder Beschriftungsfehler. Ein fehlender zentraler geforderter Anteil ergibt 0 BE für den Kern. Maximal 24 BE, bestanden ab 23 BE. Kein fehlender Kern kann durch andere Punkte kompensiert werden. Gleichwertige richtige Methoden und sinnvolle Rundungen sind zulässig, keine exakte Formulierung ist gefordert. Die zwei Fälle müssen unabhängig tatsächlich bearbeitet sein.'
 rubric_en='Grading: Eight core performances. Award 3 points for a complete scientifically correct performance; 2 only for a fully demonstrated core with one isolated non-conceptual arithmetic, rounding, or labelling slip. A missing central required component gives 0 for that core. Maximum 24; passing at 23. No absent core can be compensated by other points. Accept equivalent correct methods and sensible rounding; exact wording is not required. Both cases must actually be completed independently.'
 result={'id':ident,'shortKey':key.replace('-','_'),'title':title,'titleEn':title_en,'description':description,'descriptionEn':description_en,'weight':1,'tags':['GK','LK','Practice','Assessment','canonical'],'type':'atomic','contains':[],'requires':[covered],'dimensionTags':{**copy.deepcopy(g['dimensionTags']),'framework':'canonical-gymnasium-physics','topicCode':'CANONICAL.PHYSICS.ASSESSMENT.'+key.upper().replace('-','_')},'applicability':copy.deepcopy(g['applicability']),'extendedData':{'applicabilityFromRequires':True,'applicabilityMappingInheritance':'boundary'},'examData':{'reviewStatus':'needs_review','coveredGoalIds':[covered],'coveredStrands':g['dimensionTags'].get('guidingIdeas',[]),'demandLevels':['AB1','AB2','AB3'],'sourceArtifactPath':'curricula/DE/Gymnasium/assessments/physik/stage-source-route-repair-20261117-v1/'+key+'.md','taskContent':de,'taskContentEn':en,'solutionContent':solution_de+'\n\n'+rubric_de,'solutionContentEn':solution_en+'\n\n'+rubric_en,'scoring':{'maxPoints':24,'passingPoints':23,'steps':[{'id':k,'points':3,'description':d+' / EN: '+e} for k,d,e in criteria]}}}
 for field in ['taskContent','taskContentEn','solutionContent','solutionContentEn']:
  text=result['examData'][field]
  text=re.sub(r',(?=[A-Za-zÄÖÜäöü])', ', ', text)
  text=re.sub(r'([a-zäöüß]{2,})(?=\d)', r'\1 ', text)
  text=re.sub(r'(?<=\d)(?=[A-Za-zÄÖÜäöü])', ' ', text)
  text=re.sub(r'([;:])(?=\S)', r'\1 ', text)
  text=re.sub(r'([.!?])(?=[A-Za-zÄÖÜäöü])', r'\1 ', text)
  result['examData'][field]=text
 for field in ['title','titleEn','description','descriptionEn']:
  result[field]=re.sub(r',(?=[A-Za-zÄÖÜäöü])', ', ', result[field])
 for step in result['examData']['scoring']['steps']:
  step['description']=re.sub(r',(?=[A-Za-zÄÖÜäöü])', ', ', step['description'])
 de,en=result['examData']['taskContent'],result['examData']['taskContentEn']
 (base/(key+'.goal.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(base/(key+'.md')).write_text('# '+title+'\n\n## Deutsch\n\n'+de+'\n\n## English\n\n'+en+'\n')
 return result

fall_de='''Untersuche den freien Fall in zwei unabhängigen eigenen Messreihen A und B. Eine Beispieltabelle, ein fremdes Video oder nur ein Versuchsplan ersetzt keine Reihe. Bestimme in beiden Reihen aus eigenen grafisch ausgewerteten Messdaten g und formuliere jeweils ein Zeit-Ort-Gesetz mit ausdrücklich angegebenen Anfangsbedingungen. Ein bestimmter Wert von g darf nicht als Messergebnis vorgegeben oder durch erfundene Daten hergestellt werden.

Aufbau: Arbeite auf Fußbodenniveau in einem freien, abgesperrten kleinen Fallbereich über einer weichen Auffangmatte. Verwende einen kleinen weichen, möglichst kompakten Gummigegenstand, keine Steine, Metallgewichte oder zerbrechlichen Gegenstände. Lasse ihn aus höchstens 0,80 m ohne Stoß los; niemand befindet sich darunter. Kein Steigen auf Stühle, kein Fenster-/Treppenversuch. Die Lehrkraft prüft und stellt die sichere Aufnahmetechnik bereit. Bei Video muss eine fest montierte Kamera mindestens 120 tatsächlich aufgenommene Bilder je Sekunde liefern; kläre die reale Aufnahmebildrate, nicht nur die Abspiel- oder Exportbildrate. Eine vertikale kalibrierte Längenskala liegt in derselben Ebene wie die Fallbahn. Erfasse ihren Abstand, den Bezugspunkt am Gegenstand und die räumliche Ablesegrenze. Eine geeignete schulische Lichtschrankenanordnung mit mindestens fünf verlässlich zugeordneten Zeit-Ort-Paaren pro Fall ist gleichwertig. Handgestoppte Gesamtfallzeiten allein genügen nicht.

Vorab: Wähle einen nach unten positiven Ort x mit x=0 am tatsächlichen Loslasspunkt. Definiere, wie du den Zeitpunkt des Loslassens identifizierst und wie genau t=0, x=0 und das Loslassen näherungsweise aus Ruhe bestimmbar sind. Notiere ein erwartetes Diagrammbild als Voraussage, nicht als Messwert. Im später zu prüfenden Modell ohne Luftwiderstand gilt x(t)=x_0+v_0 t+(1/2)g t²; die Anfangsbedingungen müssen zu deiner wirklichen Auswertung passen. Das bloße Einsetzen von g=9,81 m/s² ist keine Bestimmung von g.

A – Erste tatsächliche Untersuchung: Wähle eine sichere Fallhöhe zwischen etwa 0,45 und 0,75 m. Miss und dokumentiere sie selbst. Führe mindestens drei frische Loslassversuche unter möglichst gleichen Bedingungen aus. Erfasse für jeden Versuch mindestens fünf eigene Zeit-Ort-Paare zwischen Loslassen und Auffangen, mit Bildnummern beziehungsweise eindeutigen Sensorzeitmarken. Hebe Originalaufnahmen oder Sensorprotokolle auf; eine nachvollziehbare Auswahltabelle genügt für die Abgabe, personenbezogene Aufnahmen sind unnötig. Notiere Streuung, etwaige seitliche Bewegung, Ablesegrenzen und erkennbare Stöße; kennzeichne einen begründet ungültigen Lauf, statt ihn still zu entfernen, und ersetze ihn durch einen weiteren tatsächlichen Versuch.

Werte A grafisch aus: Zeichne eigene beschriftete Diagramme mit Einheiten und sichtbaren Messpunkten. Bei begründetem v_0≈0 und geeignet gesetztem x_0 kann die Auftragung x gegen t² eine Gerade mit Steigung g/2 liefern. Bestimme die Steigung aus einer Ausgleichsgeraden über mehrere Messpunkte, nicht nur durch Verbinden zweier zufälliger Punkte. Alternativ ist eine nachvollziehbare quadratische Anpassung mit überprüften Anfangsbedingungen zulässig. Prüfe anhand der frühen Punkte und deiner Loslassmethode, ob die Annahme v_0≈0 vertretbar ist; ein Anfangsstoß darf nicht als Beleg für das Ruhemodell ausgegeben werden. Bestimme g für die gültigen Läufe, vergleiche die Werte und gib einen nachvollziehbaren Schätzwert samt aus Zeit-/Ortsablesung und Laufstreuung begründeter Größenordnung der Unsicherheit an. Verwende kein unbegründetes Konfidenzintervall. Zeige an einer sinnvollen Änderung der Zeit- oder Ortsgrenzen, wie stark dein ermitteltes g davon abhängt. Formuliere abschließend das zu A passende Zeit-Ort-Gesetz mit deinem ermittelten g, Koordinatenrichtung, Ursprung, Zeitbezug und Anfangsgeschwindigkeit.

B – Zweite unabhängige Untersuchung: Stelle eine andere sichere Fallhöhe zwischen etwa 0,25 und 0,40 m ein, miss sie und beginne eine neue Reihe mit mindestens drei eigenen Loslassversuchen. Verwende denselben Gegenstand und dieselbe sorgfältig geprüfte Skala/Zeitbasis; gleiche technische Hilfsmittel sind erlaubt, kopierte A-Daten nicht. Erzeuge für jeden gültigen B-Lauf wieder mindestens fünf frische Zeit-Ort-Paare, eigene Diagramme und eine eigene grafische Bestimmung von g beziehungsweise begründete quadratische Anpassung. Prüfe die Anfangsbedingungen erneut; übernimm nicht bloß die Freigabe aus A. Bestimme deinen B-Schätzwert samt begründeter Unsicherheitsgrößenordnung, untersuche eine Grenzvariation und formuliere ein eigenes B-Zeit-Ort-Gesetz mit allen Anfangsbedingungen.

Vergleiche zum Schluss A und B quantitativ unter Berücksichtigung der ermittelten Unsicherheiten. Erkläre, was die Daten über das gemeinsame Modell nahe der Erdoberfläche zulassen und wo Anfangsstoß, Zeitnullpunkt, Parallaxe oder Luftwiderstand die Aussage begrenzen. Ein abweichender Wert oder eine nicht auflösbare Differenz ist bei ehrlicher, geeigneter Untersuchung und begrenzter Deutung zulässig; ein erwartetes Ergebnis darf nicht erzwungen werden. Reiche beide datierten Rohprotokolle, Aufbau-/Skalenskizze, Messpunkttabellen, Diagramme, Auswertung und die beiden vollständigen Gesetze ein.'''
fall_en='''Investigate free fall in two independent personal measurement series A and B. A sample table, someone else's video, or a plan alone cannot replace either series. In each series determine g from your own graphically analysed measurements and formulate a time-position law with explicit initial conditions. No prescribed value of g may be presented as measured or manufactured by inventing data.

Setup: Work at floor level in a small clear drop area kept free of people, over a soft catching mat. Use a small soft, preferably compact rubber object, never stones, metal weights, or fragile objects. Release from at most 0.80 m without a push; nobody is beneath it. Do not climb on chairs or use windows or stairways. The teacher checks the setup and provides safe recording equipment. A fixed video camera must record at least 120 actual frames per second; verify the real acquisition rate, not merely playback or export rate. Place a calibrated vertical length scale in the plane of the fall. Record its spacing, the reference point on the object, and spatial reading limits. A suitable school photogate arrangement providing at least five reliably matched time-position pairs per fall is equivalent. Hand-timed total fall durations alone are insufficient.

Before measuring: Choose downward-positive position x, with x=0 at the actual release point. Define how you identify release and the accuracy of t=0, x=0, and approximate release from rest. Record an expected graph as a prediction, never as data. The model to be tested neglects air resistance: x(t)=x_0+v_0 t+(1/2)g t²; its initial conditions must match your analysis. Simply inserting g=9.81 m/s² does not determine g.

A – First actual investigation: Choose a safe height of approximately 0.45–0.75 m and measure it yourself. Make at least three fresh releases under conditions kept as similar as possible. Record at least five personal time-position pairs per trial between release and catching, including frame numbers or unambiguous sensor timestamps. Retain the original recording/sensor data; a traceable selected-data table is sufficient to submit, and personal images are unnecessary. Note scatter, lateral motion, reading limits, and visible pushes. Mark and justify an invalid trial rather than silently removing it, and replace it with another real trial.

Analyse A graphically: Draw your own labelled graphs with units and visible measured points. When v_0≈0 and the chosen x_0 are justified, plotting x against t² can give a line with slope g/2. Determine slope from a fitted line across several points, not simply two arbitrary points. A traceable quadratic fit with checked initial conditions is equivalent. Use early points and the release procedure to check whether v_0≈0 is defensible; a push is not evidence for release from rest. Determine g for the valid trials, compare values, and give a traceable estimate with an uncertainty scale justified by time/position readings and trial scatter, without an unsupported confidence interval. Show how a sensible change of time or position limits affects the inferred g. Finally give A's time-position law using your estimated g, axis direction, origin, time reference, and initial velocity.

B – Second independent investigation: Set and measure another safe height of approximately 0.25–0.40 m and begin a new series of at least three personal releases. Use the same object and carefully checked scale/timebase; reusing equipment is allowed, copying A's data is not. For each valid B trial produce at least five fresh time-position pairs, your own graphs, and your own graphical determination of g or justified quadratic fit. Check initial conditions again rather than copying A's conclusion. Give the independent B estimate with a justified uncertainty scale, test a boundary variation, and formulate B's own law with all initial conditions.

Finally compare A and B quantitatively with their estimated uncertainties. Explain what the data support about a common model near Earth's surface and where an initial push, time-zero error, parallax, or drag limits the conclusion. An unexpected value or unresolved difference is acceptable after an honest suitable investigation and a bounded interpretation; do not force the expected result. Submit both dated raw records, setup/scale sketch, measured-point tables, graphs, analysis, and the two complete laws.'''
fall_sd='''Es gibt keine vorgegebenen persönlichen Messwerte und keine Vorschrift, exakt g=9,81 m/s² zu erhalten. Jede Reihe benötigt eigene überprüfbare Zeit-/Ortspunkte und einen geeigneten tatsächlichen Aufbau. Für aus Ruhe und am eigenen Ursprung fallende Körper lautet das untersuchte Modell x=(g/2)t². Eine Ausgleichsgerade in x gegen t² mit Steigung m in m/s² liefert g=2m. Ein verlässlich festgestelltes v_0≠0 darf durch eine eigenständige quadratische Anpassung x=x_0+v_0t+(g/2)t² berücksichtigt werden; eine unbegründete zusätzliche freie Anpassung ersetzt keine Untersuchung der Loslassbedingungen. Für jede Reihe muss das vollständige eigene Gesetz samt Koordinatenwahl und Anfangsbedingungen nachvollziehbar sein.

Zeitverschiebung um eine Bilddauer und Positionsvariation um die reale Ablesegrenze sind mögliche nachvollziehbare Empfindlichkeitsprüfungen, keine garantierten Gesamtfehlergrenzen. Wiederholungsstreuung ersetzt systematische Skalen-/Zeitfehler nicht. Ein Ergebnis außerhalb eines Schulreferenzwertes ist nicht allein falsch; es muss auf geeigneten eigenen Daten beruhen und die begrenzte Gültigkeit des Luftwiderstandsmodells ehrlich prüfen. Aus Beispieldaten oder bloßer Planung kann kein eigener Versuch nachgewiesen werden. Für die Sicherheits-/Machbarkeitsprüfung des Aufgabenmaterials, NICHT als Lernerdaten: Bei g=9,81 m/s² beträgt die ideale Fallzeit für 0,30 m rund0,247s und für0,60m rund0,350s; bei120Bildern/s stehen somit rund30 beziehungsweise42Bildintervalle zur Verfügung. Das ermöglicht mehr als fünf räumlich verteilte Messpunkte unterhalb0,80m.'''
fall_se='''There are no prescribed personal measurements and no requirement to obtain exactly g=9.81 m/s². Each series needs traceable own time-position data and a suitable real setup. For release from rest at the chosen origin, x=(g/2)t². A fitted line in x versus t² with slope m in m/s² gives g=2m. A reliably established nonzero v_0 may be handled with an independent quadratic fit x=x_0+v_0t+(g/2)t²; unjustified extra fit parameters cannot replace investigation of release conditions. Each series needs a traceable complete own law, axis convention, and initial conditions.

Shifting time by one frame interval and positions by the actual reading limit are possible transparent sensitivity tests, not guaranteed total-error bounds. Repeat scatter does not replace systematic scale/time errors. A result differing from a school reference is not automatically wrong; it must arise from suitable own data and honestly examine limits of the drag-free model. Sample data or planning alone cannot establish personal execution. For task safety/feasibility checks ONLY, never learner data: with g=9.81 m/s² the ideal fall time is about0.247s at0.30m and0.350s at0.60m. At120frames/s these provide about30 and42frame intervals, respectively, permitting more than five spatially separated points below0.80m.'''
fall=make('personal-free-fall-two-series','09029573-864f-40ca-bf8a-cee7bf6dcb73','Prüfungsaufgabe: Freien Fall in zwei eigenen Messreihen untersuchen','Assessment: Investigate free fall in two personal measurement series','Zwei eigene sichere Falluntersuchungen mit Rohdaten, grafischer g-Bestimmung und vollständigen Zeit-Ort-Gesetzen.','Two personal safe fall investigations with raw data, graphical estimates of g, and complete time-position laws.',fall_de,fall_en,fall_sd,fall_se,[
('a-actual-data','A: Sicherer tatsächlicher Aufbau, kalibrierte reale Zeit-/Ortsskala, mindestens drei eigene gültige Läufe mit je mindestens fünf nachvollziehbaren Paaren.','A: Safe real setup, calibrated actual time/position scale, at least three own valid trials with at least five traceable pairs each.'),
('a-graph-g','A: Eigene beschriftete Messpunktdiagramme, geeignete grafische Steigung/Quadratanpassung und daraus selbst bestimmtes g für die gültigen Läufe.','A: Own labelled measured-point graphs, suitable graphical slope/quadratic fit, and independently inferred g for valid trials.'),
('a-initial-law','A: Loslassbedingungen einschließlich möglichem Anfangsstoß geprüft; eigenes vollständiges Gesetz mit x_0,v_0,g, Zeitbezug und Richtung.','A: Checks release including a possible initial push; complete own law with x_0,v_0,g,time reference,and direction.'),
('a-boundaries','A: Datenbasierter Schätzwert, reale Messgrenzen/Laufstreuung, tatsächliche Grenzvariation und begrenzte Aussage ohne erfundene Präzision.','A: Data-based estimate, real reading limits/scatter, actual boundary variation,and a bounded conclusion without invented precision.'),
('b-actual-data','B: Unabhängige zweite gemessene Höhe, mindestens drei frische eigene gültige Läufe und je mindestens fünf neue Paare, keine A-Datenkopie.','B: Independent measured second height,at least three fresh own valid trials with at least five new pairs each,no copied A data.'),
('b-graph-g','B: Neue eigene Diagramme und eigenständige quantitative grafische g-Bestimmung beziehungsweise begründete Quadratanpassung.','B: New own graphs and independent quantitative graphical g determination or justified quadratic fit.'),
('b-initial-law','B: Anfangsbedingungen erneut tatsächlich geprüft und separates vollständiges B-Zeit-Ort-Gesetz formuliert.','B: Actually rechecks initial conditions and formulates a separate complete B time-position law.'),
('b-boundaries-comparison','B: Eigene Unsicherheits-/Grenzvariation und quantitativer A/B-Vergleich mit begründeter Modellgrenze, kein erzwungenes Ergebnis.','B: Own uncertainty/boundary variation and quantitative A/B comparison with justified model limits,no forced result.')])

doc_de='''Erstelle zu den beiden Materialfällen A und B jeweils ein eigenes vollständiges und gut nachvollziehbares physikalisches Versuchsprotokoll. Die unten ausdrücklich als didaktisch bereitgestellten Aufzeichnungen sind KEINE von dir erhobenen Messungen und keine Behauptung eines tatsächlich beobachteten Versuchs. Du sollst sie selbst auswählen, ordnen, auswerten und dokumentieren; eine übernommene Musterlösung oder bloß ausgefüllte Überschriften genügen nicht. Du musst für diese Dokumentationsaufgabe keinen eigenen Versuch durchführen. Beide Protokolle müssen für eine andere Person verständlich machen, was untersucht wurde, wie es untersucht wurde, welche Beobachtungen/Messwerte vorliegen, wie daraus Ergebnisse entstehen und welche Grenzen diese haben. Trenne bereitgestellte Beobachtungen, eigene Rechnungen, Annahmen und Schlussfolgerungen eindeutig.

Material A – Wagen auf einer horizontalen Bahn, ungeordnete didaktische Laborzettel: Fragestellung: „Welche mittlere Geschwindigkeit hat der Wagen im markierten Abschnitt unter den beschriebenen Startbedingungen?“ Zwei Marken A und B wurden mit dem Maßband auf einer ebenen Bahn gesetzt; Abstand zwischen den Marken 0,600 m, geschätzte Ablesegrenze ±0,005 m. Gemessen wird vom Passieren der Marke A durch die vordere Achse bis zum Passieren der Marke B durch dieselbe Achse. Vor A wurde der Wagen jeweils von Hand sanft angeschoben; die Anschubstärke wurde nur angenähert gleich gehalten. Der Wagen rollte in allen gültigen Läufen in dieselbe Richtung durch beide Marken; keine Kollision, Beobachtung der vorderen Achse. Eine Person startete/stoppte eine Stoppuhr; Anzeige in0,1s, geschätzte Reaktions-/Zuordnungsgrenze ±0,2s pro gemessener Gesamtzeit. Vorversuch P:2,0s, noch mit verändertem Anschub und vor Festlegung der endgültigen Methode; ausdrücklich kein gültiger Wiederholungslauf. Gültige Läufe A1:2,4s; A2:2,5s; A3:2,6s. Datum der bereitgestellten Aufzeichnung:14.11.2026. Auswertungsregel: mittlere Geschwindigkeit im Abschnitt v=s/t; berechne sie für jeden gültigen Lauf und anschließend den arithmetischen Mittelwert dieser drei v-Werte. Gib auch die beobachtete Spannweite an. Eine Aussage über die momentane Geschwindigkeit an jedem Bahnpunkt folgt daraus nicht.

Protokoll A: Formuliere die Fragestellung, beschreibe Material/Aufbau und den Messablauf mit den tatsächlichen Bezugspunkten aus den Zetteln. Eine eigene beschriftete Skizze darf den Text ersetzen, wenn sie alle nötigen Angaben enthält. Erstelle eine geordnete Tabelle aller Daten; kennzeichne den Vorversuch, dokumentiere die Begründung seiner getrennten Behandlung und bewahre seinen Wert in der Dokumentation. Zeige deine eigenen Auswertungsschritte mit einer nachvollziehbaren Beispielrechnung, allen drei Ergebnissen, Mittelwert und Spannweite samt Einheiten. Gib die bereitgestellten Messgrenzen korrekt an und unterscheide sie von der beobachteten Streuung. Beantworte die Frage in einem begründeten Ergebnisabsatz und nenne anhand des konkreten Aufbaus eine Grenze; behaupte weder perfekt gleiche Anschubbedingungen noch eine überall konstante Momentangeschwindigkeit.

Material B – Eigenständiger zweiter Dokumentationsfall, Fadenpendel: Fragestellung: „Welche Periodendauer zeigt dieses Pendel bei den beschriebenen kleinen Auslenkungen?“ Aufbau: kleines Pendelgewicht an einem Faden, feste Aufhängung; Abstand Aufhängung bis Schwerpunkt40,0cm mit Ablesegrenze±0,5cm. Auslenkung ungefähr5°; aus Ruhe losgelassen, keine Berührung während der Messung. Eine vollständige Periode wird von der rechten Umkehrlage bis zur nächsten rechten Umkehrlage gezählt. Gemessen wurde für20volle Perioden; Start und Stopp erfolgten an derselben rechten Umkehrlage. Stoppuhranzeige0,1s; geschätzte Zuordnungs-/Reaktionsgrenze der gesamten Zeit±0,2s. Gültige Läufe B1:26,0s; B2:25,8s; B3:26,2s. Zusätzlicher Zettel B4:26,1s, daneben „Anzahl15oder20? Zählung nicht verlässlich“; der Zeitwert ist dokumentiert, die Periodenzahl aber nicht gesichert. Beobachtung: Ausschläge wurden allmählich kleiner, die Bewegung blieb sichtbar in einer Ebene. Datum der bereitgestellten Aufzeichnung:15.11.2026. Auswertungsregel: T=t/N, wobei N die verlässlich gezählte Zahl vollständiger Perioden ist. Es soll weder g noch ein Pendelgesetz hergeleitet werden.

Protokoll B: Erstelle unabhängig von A einen vollständigen strukturierten Bericht mit Fragestellung, Aufbau, Messdefinition, Beobachtungen und allen Rohwerten einschließlich B4. Entscheide begründet, welche Werte einen belastbaren Mittelwert von T zulassen; erfinde keine Periodenzahl für B4 und entferne ihn nicht still. Berechne T für jeden gültigen Lauf selbst sowie Mittelwert und Spannweite mit nachvollziehbarer Beispielrechnung und Einheiten. Unterscheide Messgrenzen, beobachtete Streuung und die fehlende Information bei B4. Formuliere ein aus diesen Daten begründetes Ergebnis mit konkreter Grenze. Eine sorgfältig erklärte andere fachtypische Darstellungsform ist gleichwertig, sofern sämtliche Beobachtungen, Messwerte, Auswertung und Ergebnisse für eine andere Person lückenlos nachvollziehbar bleiben.'''
doc_en='''Write your own complete, traceable physical investigation report for each material case A and B. The records below are explicitly didactic supplied material, NOT measurements you collected or a claim of an actually observed experiment. You must organise, evaluate, and document them yourself; a copied model answer or headings alone is insufficient. You need not perform an experiment for this documentation task. Each report must let another person understand the question, method, observations/data, how results were derived,and their limits. Clearly separate supplied observations,your calculations,assumptions,and conclusions.

Material A – Cart on a horizontal track,unordered didactic notes: Question: 'What mean speed does the cart have within the marked section under the stated starting conditions?' Marks A and B were set using a tape measure on a level track; their separation is0.600m with estimated reading limit±0.005m. Timing starts when the front axle passes A and ends when the same axle passes B. Before A the cart was gently pushed by hand; push strength was kept only approximately similar. In all valid trials it passed both marks in the same direction without collision; observers watched the front axle. One person started/stopped a stopwatch displaying0.1s; the estimated reaction/assignment limit is±0.2s for each total interval. Pilot P:2.0s,with a different push before the final method was fixed; explicitly not a valid repeat. Valid trials A1:2.4s;A2:2.5s;A3:2.6s. Supplied-record date:14November2026. Analysis rule: mean speed within the section v=s/t; calculate it for each valid trial,then take the arithmetic mean of those three speed values. Also report observed range. This does not determine instantaneous speed at every point.

Report A: State the question,apparatus/setup,and procedure using the reference points in the notes. A labelled sketch may replace text if it contains all required information. Organise all raw data in a table;label the pilot,justify its separate treatment,and retain its value in the report. Show your own evaluation steps,one traceable example,all three results,mean,and range with units. Correctly report the supplied reading limits and distinguish them from observed scatter. Answer the question in a justified conclusion with a setup-specific limitation;claim neither perfectly identical pushes nor constant instantaneous speed throughout.

Material B – Independent second documentation case,a simple pendulum: Question: 'What period does this pendulum show at the stated small amplitudes?' Setup: a small mass on a string with a fixed support; pivot-to-centre-of-mass distance40.0cm,reading limit±0.5cm. Amplitude approximately5°;released from rest with no contact during timing. A full period is counted from the right turning point to the next right turning point. Timing covers20complete periods;start and finish occur at the same right turning point. Stopwatch display0.1s;estimated reaction/assignment limit for the total interval±0.2s. Valid trials B1:26.0s;B2:25.8s;B3:26.2s. Additional note B4:26.1s,beside '15or20periods? Count unreliable';time is recorded but period count is not established. Observation: amplitudes gradually decreased and motion remained visibly in one plane. Supplied-record date:15November2026. Analysis rule:T=t/N,where N is the reliably counted number of complete periods. Do not derive g or a pendulum law.

Report B: Independently produce a complete structured report with question,setup,measurement definition,observations,and all raw values including B4. Justify which data support a mean T;do not invent B4's count or silently delete it. Calculate T yourself for each valid trial and the mean and range,with a traceable worked example and units. Distinguish reading limits,observed scatter,and missing information in B4. Give a data-based conclusion with a concrete limitation. Another clearly explained subject-appropriate format is equally valid if another person can trace every observation,measurement,evaluation step,and result.'''
doc_sd='''A: Die drei Geschwindigkeiten sind 0,600/2,4=0,250 m/s; 0,600/2,5=0,240 m/s; 0,600/2,6≈0,23077 m/s. Ihr arithmetischer Mittelwert ist ≈0,24026 m/s, sinnvoll etwa 0,24 m/s. Der beobachtete Bereich reicht von ≈0,231 bis 0,250 m/s (Spannweite ≈0,0192 m/s). P bleibt als Vorversuch mit 2,0 s und Begründung im Protokoll, geht aber nicht in den Wiederholungsmittelwert ein. Die Längengrenze ±0,005 m und die geschätzte Zeitzuordnung ±0,2 s sind angegebene Messgrenzen, keine aus drei Wiederholungen berechneten Konfidenzintervalle. Handanschub und manuelles Timing begrenzen Vergleichbarkeit und Präzision; aus Abschnittszeiten folgt keine Momentangeschwindigkeit oder bewiesene Geschwindigkeitskonstanz.

B: T-Werte 1,300 s; 1,290 s; 1,310 s, Mittelwert 1,300 s, beobachteter Bereich 1,290–1,310 s (Spannweite 0,020 s). B4 muss mit 26,1 s und fehlender verlässlicher Zählung dokumentiert bleiben. Erfundenes 15 oder 20 als gesicherte Zahl wäre unzulässig; ohne sicheres N ist B4 kein belastbarer Periodenwert für diesen Mittelwert. Die angegebene Zeitgrenze ±0,2 s für 20 Perioden entspräche allein bei fester Zählung ±0,010 s pro Periode; dies ist optional, keine Pflicht einer zusätzlichen Unsicherheitsrechnung. Berichte kleiner werdende Amplitude, Bezugspunkte und Zählverfahren, ohne eine Ursache oder absolut konstante Periodenlänge zu beweisen. Nachvollziehbares Dokumentieren und Rechnen ist gefragt, kein Beweis des Pendelgesetzes.

In beiden Berichten sind die vorgegebenen didaktischen Aufzeichnungen als Quelle gekennzeichnet. Die Lernleistung ist die eigene vollständige Dokumentation und Auswertung, keine Behauptung eines persönlichen Versuchs. Eine andere geordnete Darstellung darf gleichwertig sein; es gibt keine Pflicht, bestimmte Überschriften wortgleich zu kopieren.'''

doc_se='''A: Individual speeds are0.600/2.4=0.250m/s;0.600/2.5=0.240m/s;0.600/2.6≈0.23077m/s. Their arithmetic mean is≈0.24026m/s,reasonably reported as about0.24m/s. Observed range is about0.231–0.250m/s(width≈0.0192m/s). Keep pilot P=2.0s with its reason in the report,but exclude it from the repeat mean. The supplied±0.005m length limit and estimated±0.2s timing assignment are measurement limits,not confidence intervals calculated from three repeats. Hand pushing and timing limit comparability and precision;section times determine neither instantaneous speed nor proven constant motion.

B: Periods are1.300s,1.290s,1.310s;mean1.300s,observed range1.290–1.310s(width0.020s). B4 must remain documented with26.1s and its unreliable count. Inventing15or20as established is invalid;without a known N,B4 cannot support this mean period. A±0.2s total-time limit over a fixed20periods alone corresponds to±0.010s per period;this is optional,not an additional required uncertainty calculation. Report decreasing amplitude,reference points,and counting method without claiming a proven cause or absolutely constant period. The task needs traceable recording/calculation,not a pendulum-law derivation.

Both reports identify the didactic supplied records as their source. The learner performance is complete independent documentation and analysis,not a claim of personal experimentation. Another organised representation can be equivalent;no exact section-heading wording is required.'''
document=make('document-two-provided-investigations','ad62f563-4fee-5399-8d9c-03a214658aa9','Prüfungsaufgabe: Zwei Untersuchungen nachvollziehbar dokumentieren','Assessment: Document two investigations traceably','Zwei eigene vollständige Versuchsprotokolle aus klar bezeichnetem didaktischem Rohmaterial mit Beobachtung, Messwerten, eigener Auswertung und begrenzten Ergebnissen.','Two own complete reports from explicitly didactic raw material,including observations,measurements,own evaluation,and bounded results.',doc_de,doc_en,doc_sd,doc_se,[
('a-question-method','A: Frage, Aufbau, Bezugspunkte und Ablauf klar und anhand des Materials nachvollziehbar beschrieben.','A: Clearly and traceably documents question,setup,reference points,and procedure from the material.'),('a-raw-observations','A: Alle Beobachtungen und Rohwerte mit Einheiten/Messgrenzen, Vorversuch erkennbar erhalten und nachvollziehbar getrennt.','A: Preserves all observations/raw values with units/reading limits;clearly retains and justifies separate pilot handling.'),('a-own-evaluation','A: Eigene nachvollziehbare Rechnungen mit drei Geschwindigkeiten, deren Mittelwert und Spannweite; Rechenweg/Einheiten vollständig.','A: Own traceable calculations of three speeds,their mean and range,with complete steps/units.'),('a-result-limit','A: Ergebnis beantwortet die Frage, trennt Streuung/Messgrenzen/Annahmen und begrenzt die Aussage konkret; didaktische Quelle transparent.','A: Conclusion answers the question,distinguishes scatter/reading limits/assumptions,and gives a concrete limitation;didactic source explicit.'),('b-question-method','B: Eigenständiger vollständiger Aufbau-/Methodenbericht mit Länge, kleinen Auslenkungen und eindeutiger vollständiger Periodenzählung.','B: Independent complete setup/method report with length,small amplitude,and unambiguous full-period counting.'),('b-raw-observations','B: Sämtliche Beobachtungen/Rohwerte einschließlich ungesichertem B4 nachvollziehbar dokumentiert, keine erfundene Periodenzahl.','B: Traceably documents every observation/raw value including uncertain B4,without inventing a period count.'),('b-own-evaluation','B: Eigene drei Periodenberechnungen mit Beispiel, Mittelwert und Spannweite; B4 begründet getrennt und nicht still entfernt.','B: Own three period calculations with a worked example,mean,and range;justifiably separates B4 without silently removing it.'),('b-result-limit','B: Eigenes begründetes Ergebnis mit konkreter Mess-/Beobachtungsgrenze und vollständiger Trennung von Quelle, Rechnung und Schlussfolgerung.','B: Own justified conclusion with a concrete measurement/observation limit and clear distinction between source,calculation,and inference.')])

motor_de='''Baue einen einfachen Elektromotor in zwei unabhängigen eigenen Aufbauten A und B auf und untersuche jeweils eine Veränderung seines Laufs. Du musst beide Aufbauten selbst aus den bereitgestellten offenen Schulbauteilen herstellen, ihre wirklichen Beobachtungen protokollieren und die Funktion mit der Kraft auf stromdurchflossene Leiter im Magnetfeld erklären. Ein fertig gekapselter Motor, eine Simulation, ein fremdes Protokoll oder eine bloße Aufbauplanung ersetzt keine der beiden Leistungen.

Bereitgestelltes Material: Ein schulisch erprobter offener Kleinspannungs-Motorbausatz mit drehbar gelagerter Spule, zwei getrennten Kommutatorhälften K1/K2 mit je einem verbundenen Spulenende S1/S2, zwei gegenüberliegenden Bürstenkontakten B1/B2, Halterungen, zwei Ferritmagneten mit gekennzeichnetem N-/S-Pol, Anschlussleitungen und Schalter. Die Lehrkraft stellt eine strombegrenzte Gleichspannungsversorgung mit höchstens3,0V und Stromgrenze höchstens0,3A bereit und prüft den Aufbau vor jedem Einschalten. Keine Netzspannungsarbeiten, keine Lithiumzellen oder offenen Batteriekurzschlüsse. Nur am ausgeschalteten Aufbau umstecken. Betreibe den Motor nur kurz zur Beobachtung; bei Erwärmung, blockiertem Rotor oder beschädigten Leitungen sofort ausschalten und die Lehrkraft prüfen lassen. Hände, Haare und lose Teile vom Rotor fernhalten. Der niedrige begrenzte Strom ist keine Aufforderung, die Kontakte absichtlich kurzzuschließen.

Aufbauvorgabe: S1 ist mit K1, S2 mit K2 verbunden; die Spule und der geteilte Kommutator drehen sich gemeinsam. B1 und B2 liegen gegenüber an den Kommutatorhälften an und sind mit den beiden Polen der Versorgung über den Schalter verbunden. Richte die beiden Magnetpole gegenüber so aus, dass die Spule im Feldspalt frei drehen kann. Welche Spulenseite bei deinem Aufbau nach vorne/hinten liegt, musst du selbst eindeutig skizzieren. Du darfst einen gleichwertigen geprüften offenen Schulbausatz verwenden, wenn du dessen Kontakte, Lagerung, Feldrichtung und Beobachtungen ebenso eindeutig dokumentierst. Ein Handanstoß zum Überwinden einer Totlage ist nach Prüfung erlaubt, muss aber protokolliert werden; er ist keine elektrisch bewirkte selbständige Drehung.

A – Eigener erster Aufbau und Stromumkehr: Baue den Motor selbst auf. Weise für A mindestens einen Lauf nach, bei dem der Rotor nach Loslassen elektrisch selbständig weiterläuft. Nur Stillstand oder fortgesetztes Handdrehen erfüllt die Aufbauleistung nicht. Behebe nötige Fehler mit sicherer Prüfung und führe anschließend die kontrollierte Variation tatsächlich auswertbar durch; bei fehlender Funktion ist Nacharbeit erforderlich, kein erfundener Erfolg. Fertige eine eigene beschriftete Aufbau-/Schaltskizze mit Spule, beiden aktiven Leiterseiten, K1/K2, B1/B2, Schalter und tatsächlichen Versorgungspolen an. Kennzeichne für eine gewählte Rotorstellung Magnetfeld- und Stromrichtung in beiden aktiven Leiterseiten. Lege eine feste Blickrichtung fest, damit „rechts-/linksherum“ eindeutig ist. Sage vor dem Versuch voraus, was bei alleiniger Umkehr der Versorgungspole zu erwarten ist, und begründe dies mit den Leiterkräften.

Beobachte mindestens drei kurze tatsächliche Starts mit Ausgangspolung und drei mit umgekehrter Polung bei gleicher Feldanordnung, Spannungseinstellung und Mechanik. Notiere je Start tatsächliche Laufrichtung beziehungsweise Stillstand, benötigten Anstoß, etwaige Totlage oder Kontaktunterbrechung. Es gibt keine vorgeschriebene Drehzahl. Wähle keine scheinbar passenden Beobachtungen aus; dokumentiere Störungen und führe nach sicherer Prüfung nötige Kontrollen aus. Erkläre mit deiner eigenen Skizze die entgegengesetzten Kräfte an den beiden stromdurchflossenen Leiterseiten und ihre Drehwirkung. Erkläre außerdem, wie die realen Bürsten-/Kommutatorkontakte in deinem Aufbau fortgesetzte Drehung ermöglichen, statt dass der Rotor nur einmal in eine Ruhelage ausschlägt. Vergleiche Vorhersage und wirkliche Beobachtung; falls der Motor nicht zuverlässig läuft, überprüfe und korrigiere nachvollziehbar den eigenen Aufbau, bis eine auswertbare Untersuchung möglich ist. Erfunde keine erfolgreichen Starts.

B – Zweiter eigener Aufbau und Feldumkehr: Für B ist erneut mindestens ein nach Loslassen elektrisch selbständig weiterlaufender Lauf erforderlich. Ein reiner Stillstandsaufbau oder Handdrehen genügt nicht; behebe Fehler und mache die anschließende kontrollierte Variation auswertbar, sonst ist Nacharbeit erforderlich. Schalte aus, zerlege den Aufbau in seine Montagebauteile und baue ihn selbst neu auf. Dieselben geeigneten Teile dürfen wiederverwendet werden; eine unveränderte Übernahme von A samt Daten genügt nicht. Dokumentiere den neuen Aufbau und seine tatsächliche Kontakt-/Feldgeometrie in einer neuen Skizze. Halte diesmal die Versorgungspolung unverändert und kehre nur die Magnetfeldrichtung um, indem du die beiden gegenüberliegenden Pole tauschst. Prüfe vorher, dass der Rotor weiterhin frei liegt und die Feldanordnung technisch gleichwertig ist. Notiere zuerst deine eigene begründete Vorhersage.

Untersuche mit mindestens drei frischen Starts vor und drei nach Feldumkehr, bei sonst gleicher Einstellung. Protokolliere sämtliche Laufrichtungen/Stillstände und Hilfsanstöße sowie begründete Kontrollen. Erkläre an beiden aktiven Leiterseiten erneut Feld-, Strom- und Kraftrichtung sowie Drehwirkung und Kommutierung für B. Werte B eigenständig aus und vergleiche erst danach die beiden untersuchten Eingriffe: Was wird jeweils verändert, was bleibt gleich, und was begründet deine Aussage über den Motorlauf? Eine beobachtete Störung ist kein Beweis gegen die Leiterkraftregel; benenne die tatsächliche begrenzte Beobachtung und kontrolliere mögliche Kontakt-/Totlagenfehler, statt eine passende Erklärung zu erfinden. Reiche zwei datierte tatsächliche Startprotokolle, die beiden eigenen Skizzen, Vorhersagen, Kontrollen und Erklärungen ein.'''
motor_en='''Build a simple electric motor in two independent personal setups A and B and investigate a change of its motion in each. Assemble both yourself from the supplied open school components,record actual observations,and explain operation using forces on current-carrying conductors in a magnetic field. An enclosed ready-made motor,simulation,somebody else's record,or a plan alone cannot replace either performance.

Supplied equipment: A school-tested open low-voltage motor kit with a supported rotating coil,two separate commutator halves K1/K2 connected to coil ends S1/S2,two opposing brushes B1/B2,holders,two ferrite magnets with marked N/S poles,wires,and a switch. The teacher provides a current-limited DC supply set to at most3.0V and at most0.3A and checks the circuit before each activation. No mains work,lithium cells,or exposed battery shorts. Reconnect only with power off. Operate briefly for observation;switch off immediately for heating,a blocked rotor,or damaged wires,and ask the teacher to inspect. Keep hands,hair,and loose objects clear of the rotor. Limited low current is not permission to deliberately short contacts.

Assembly specification: S1 connects to K1 and S2 to K2;coil and split commutator rotate together. Opposing brushes B1/B2 contact the commutator and connect to the two supply poles through the switch. Place opposing magnet poles so the coil rotates freely in the gap. Clearly sketch which coil side faces forward/backward in your actual setup. An equivalent checked open school kit is allowed if its contacts,bearings,field direction,and observations are equally explicit. A gentle starting nudge out of a dead position is allowed after inspection but must be recorded;it is not electrically sustained rotation.

A – Personal first assembly and current reversal: Assemble the motor yourself. For A demonstrate at least one run in which the rotor continues rotating electrically on its own after release. Standstill or continued hand-turning does not meet the assembly requirement. Safely diagnose and correct faults, then actually perform an analysable controlled variation; absent motor function requires further work, never invented success. Draw your own labelled setup/circuit showing coil,both active conductor sides,K1/K2,B1/B2,switch,and actual supply polarity. For one chosen rotor position show magnetic-field and current directions on both active conductor sides. Define a fixed viewing direction so clockwise/counterclockwise are unambiguous. Predict before testing the effect of reversing only supply polarity,and justify using conductor forces.

Observe at least three real brief starts with original polarity and three with reversed polarity,keeping field,voltage setting,and mechanics unchanged. Record every start's actual rotation direction or standstill,required nudge,dead position,or contact interruption. No speed is prescribed. Do not select convenient observations;record disturbances and perform necessary controls after safe inspection. Use your own sketch to explain opposite forces on the two active current-carrying sides and their rotational effect. Also explain how your actual brush/commutator contacts permit continued rotation rather than one deflection into a resting position. Compare prediction with observation;if operation is unreliable,traceably check and correct your own assembly until an analysable investigation is possible. Do not invent successful starts.

B – Second personal assembly and field reversal: For B again demonstrate at least one electrically sustained run after release. A stationary assembly or hand-turning is insufficient: correct faults and make the subsequent controlled variation analysable, or undertake further work. Switch off,disassemble into mounting components,and rebuild it yourself. You may reuse suitable parts;leaving A unchanged and copying its data is insufficient. Document the new assembly and actual contact/field geometry in a new sketch. Keep supply polarity fixed this time and reverse only field direction by swapping the opposing poles. First check free rotation and an otherwise technically equivalent field arrangement. Record your own justified prediction before testing.

Investigate at least three fresh starts before and three after field reversal with other settings unchanged. Record every direction/standstill,nudge,and justified control. Again explain field,current,force,and rotation on both active sides and commutation for B. Analyse B independently before comparing the interventions:what changes,what remains fixed,and what supports your conclusion about motor motion? A disturbed start is not evidence against the conductor-force rule;report the actual bounded observation and control possible contact/dead-position faults instead of inventing a convenient explanation. Submit two dated actual start records,both own sketches,predictions,controls,and explanations.'''
motor_sd='''Es sind keine Laufrichtungen ohne tatsächliche Blick-/Wicklungs-/Feldgeometrie als Musterwert vorgeschrieben. Die beiden aktiven Spulenseiten tragen entgegengesetzte Ströme im gemeinsamen Magnetfeld; ihre Kräfte sind entgegengesetzt und erzeugen in geeigneter Rotorstellung eine gemeinsame Drehwirkung. Eine korrekte räumliche Kraftrichtung ergibt sich aus der im jeweiligen Aufbau angewandten Leiterkraftregel. Umkehr allein des Stroms kehrt die Kräfte und damit die Drehwirkung um. Umkehr allein des Magnetfeldes tut dies ebenfalls. Bei gleichzeitiger Strom- und Feldumkehr wäre die ursprüngliche Kraftrichtung wiederhergestellt; diese Zusatzvariation ist nicht verpflichtend und darf die beiden verlangten echten Untersuchungen nicht ersetzen.

Der geteilte Kommutator und die gegenüberliegenden Bürsten verbinden die beiden Spulenenden nach einer halben Umdrehung mit vertauschten äußeren Versorgungspolen. Die dann vertauschte interne Stromrichtung erhält die antreibende Drehwirkung über die veränderte Rotorlage hinweg; eine Skizze oder mündliche räumliche Erläuterung mit nachvollziehbarer eigener Darstellung ist gleichwertig. Eine vorhandene Totlage, ein nötiger kurzer Anstoß oder Kontaktstörungen werden getrennt von elektrisch aufrechterhaltener Drehung dokumentiert. Aus bloßem von Hand gedrehtem Rotor folgt keine Motorfunktion. Ohne mindestens einen elektrisch selbständig weiterlaufenden Lauf nach Loslassen in jedem Aufbau sind die jeweiligen Aufbau-Kerne nicht vollständig; ohne anschließend auswertbare kontrollierte Variation sind auch die Variationskerne nicht vollständig. Ein nicht funktionsfähiger Aufbau verlangt Nacharbeit statt voller Freigabe. Beide eigenen Aufbauten und jeweils die kontrollierte tatsächliche Variation müssen aus den Datensätzen hervorgehen; kopierte oder erfundene Starts sind kein Nachweis. Nicht gefordert sind quantitative Drehzahl-, Wirkungsgrad- oder Transformatorrechnungen.'''
motor_se='''No rotation-direction sample is prescribed without the actual viewing,winding,and field geometry. The two active coil sides carry opposite currents in a common magnetic field;their opposite forces create a common rotational effect at a suitable rotor position. Correct spatial force direction follows the conductor-force rule applied to the actual setup. Reversing only current reverses force and torque;reversing only the magnetic field does so too. Reversing both would restore the original force direction;this extra variation is optional and cannot replace the two required real investigations.

After half a turn,the split commutator and opposing brushes connect the two coil ends to swapped external supply poles. The reversed internal current maintains the driving rotational effect as rotor orientation changes. A traceable own sketch or spatial explanation is equally valid. Record dead positions,starting nudges,and contact faults separately from electrically sustained rotation. A rotor turned only by hand does not establish motor operation. Each assembly core requires at least one electrically sustained run after release, and each variation core requires an analysable controlled test after any necessary fault correction. A nonfunctional assembly requires further work rather than full credit. Both personal assemblies and their controlled actual variations must be evident from records;copied or invented starts are not evidence. No quantitative speed,efficiency,or transformer calculations are required.'''
motor=make('personal-motor-two-builds','eb30189c-27c6-510b-b235-6543afa18b90','Prüfungsaufgabe: Zwei eigene Motoraufbauten und Laufvariationen','Assessment: Two personal motor assemblies and motion variations','Zwei eigene sichere offene Motoraufbauten mit frischen Startbeobachtungen, kontrollierter Strom-/Feldvariation und vollständiger Leiterkrafterklärung.','Two personal safe open motor assemblies with fresh start observations,controlled current/field variations,and complete conductor-force explanations.',motor_de,motor_en,motor_sd,motor_se,[
('a-own-build','A: Eigener realer geprüfter Aufbau mit mindestens einem nach Loslassen elektrisch selbständig weiterlaufenden Lauf, eigener vollständiger Kontakt-/Feld-/Versorgungsskizze und Blickrichtung; Stillstand/Handdrehen allein ist kein vollständiger Kern.','A: Own real checked assembly with at least one electrically sustained run after release, complete own contact/field/supply sketch and viewing direction; standstill/hand-turning alone cannot complete this core.'),('a-actual-variation','A: Begründete Vorhersage und mindestens drei echte Starts pro Strompolung, feste übrige Bedingungen, alle Beobachtungen/Kontrollen transparent.','A: Justified prediction and at least three real starts per current polarity,other conditions fixed,all observations/controls transparent.'),('a-force-operation','A: Beide aktiven Leiterseiten mit richtigen Strom-/Feld-/Kraftrichtungen und gemeinsamer Drehwirkung am eigenen Aufbau erklärt.','A: Explains both active sides with correct current/field/force directions and their common rotational effect in the own assembly.'),('a-commutation-result','A: Reale Kommutierung und fortgesetzter Antrieb nachvollziehbar erklärt, mit Beobachtungen abgeglichen; Handanstoß/Störung nicht als Motorantrieb ausgegeben.','A: Traceably explains actual commutation/continued drive and compares with observation;does not confuse a nudge/fault with motor drive.'),('b-own-build','B: Tatsächlich neu selbst montierter Aufbau mit mindestens einem elektrisch selbständig weiterlaufenden Lauf nach Loslassen und eigener neuer Skizze; keine unveränderte A-Übernahme, Stillstand/Handdrehen allein ist kein vollständiger Kern.','B: Actually reassembles personally with at least one electrically sustained run after release and a new clear own sketch; not unchanged A, and standstill/hand-turning alone cannot complete this core.'),('b-actual-variation','B: Eigene begründete Feldumkehrvorhersage und mindestens drei frische Starts je Feldrichtung bei fester Polung; vollständige Beobachtungen/Kontrollen.','B: Own justified field-reversal prediction and at least three fresh starts per field direction at fixed polarity;complete observations/controls.'),('b-force-operation','B: Leiterkräfte, Strom-/Feldrichtung, Drehwirkung und Kommutierung erneut am tatsächlichen zweiten Aufbau vollständig erklärt.','B: Again completely explains conductor forces,current/field directions,torque,and commutation in the actual second setup.'),('b-independent-comparison','B: Eigenständige Auswertung und begrenzter Vergleich beider kontrollierter Variationen mit tatsächlichen Ergebnissen, Störungen nachvollziehbar geprüft.','B: Independent analysis and bounded comparison of controlled variations using actual results and traceable fault checks.')])

